import pandas as pd

def find_winner(new_york: pd.DataFrame, california: pd.DataFrame) -> pd.DataFrame:
    ny_count = (new_york['score'] >= 90).sum()
    ca_count = (california['score'] >= 90).sum()
    if ny_count > ca_count:
        w = 'New York University'
    elif ca_count > ny_count:
        w = 'California University'
    else:
        w = 'No Winner'
    return pd.DataFrame([{'winner': w}])
